<script setup lang="ts">
import {ref} from 'vue';
import {useProjectStore} from '../stores/project';
import {createSettingsEditor} from '../lib/settings';
import type {StudioSettingsSnapshot,StudioModuleDefault,StudioConnectionMetadata,StudioDefaults} from '@loreviva/sdk-ts';
import FieldErrors from './FieldErrors.vue';
const props=defineProps<{snapshot:StudioSettingsSnapshot}>();const s=useProjectStore();const editor=createSettingsEditor(s.client,props.snapshot);const {local,basis,pending,dirty}=editor;const error=ref<unknown>();const message=ref('');
const modules=['INTERACTION','PROACTIVE','AUTHORING','KNOWLEDGE_EXTRACTION','MEDIA','REHEARSAL','EVALUATION'] as const;
// These controls edit local defaults and connection metadata, not provider readiness. Connection commands use the accepted basis revision; the settings editor owns section-specific saves and original-receipt recovery.
function module(mode:string,id:typeof modules[number]){const existing=local.value.defaults.module_defaults.find(d=>d.module_id===id);if(existing){existing.generation_settings.mode=mode as 'NONE'|'INHERIT'|'OVERRIDE';if(mode==='OVERRIDE'){existing.generation_settings.connection_ref='mock-local';existing.generation_settings.model_id='synthetic-text-v1'}}else{const g:StudioModuleDefault={module_id:id,generation_settings:{mode:mode as 'NONE'|'INHERIT'|'OVERRIDE',required_capabilities:['TEXT'],allowed_external_uses:['NONE'],...(mode==='OVERRIDE'?{connection_ref:'mock-local',model_id:'synthetic-text-v1'}:{})}};local.value.defaults.module_defaults=[...local.value.defaults.module_defaults,g] as StudioDefaults['module_defaults']}}
async function save(section:'DEFAULTS'|'NOTIFICATIONS'|'QUOTA'){try{const r=await editor.save(section);message.value='已保存 '+r.kind+'，修订 '+r.result_revision;error.value=undefined}catch(e){error.value=e}}
async function connection(c:StudioConnectionMetadata,disable=false){try{const expected=basis.value.connections.find(x=>x.connection_id===c.connection_id)?.revision??'0';const r=await editor.command(disable?{scope:basis.value.basis.scope,kind:'DISABLE_CONNECTION',connection_id:c.connection_id,expected_revision:expected}:{scope:basis.value.basis.scope,kind:'UPSERT_CONNECTION_METADATA',connection:{...c,revision:expected},expected_revision:expected});message.value='连接状态已保存，修订 '+r.result_revision;error.value=undefined}catch(e){error.value=e}}
async function recover(){try{const r=await editor.recover();message.value='已取得原回执 '+r.command_key;error.value=undefined}catch(e){error.value=e}}
function addConnection(){local.value.connections.push({connection_id:'',revision:'0',name:'',provider_ref:'',model_id:'',endpoint_alias_ref:'',secret_alias_ref:'',status:'R1_REQUIRED'})}
</script>
<template><FieldErrors :error="error"/><p v-if="dirty" class="badge warm">有未保存的设置修改；已提交修订与本地编辑分别保留。</p><p v-if="message" role="status" class="success">{{message}}</p><p v-if="pending">原操作结果尚待确认：{{pending.operation}}。<button @click="recover">查原设置回执</button></p><section class="panel"><h2>七模块默认设置</h2><p>对象、岗位覆盖优先；这里的配置用于没有覆盖的新请求。NONE 明确禁用。MEDIA 当前没有合成生成能力。</p><label v-for="id in modules" :key="id">{{id}}<select :value="local.defaults.module_defaults.find(d=>d.module_id===id)?.generation_settings.mode??'INHERIT'" @change="module(($event.target as HTMLSelectElement).value,id)"><option value="INHERIT">继承</option><option value="NONE">不生成</option><option v-if="id!=='MEDIA'" value="OVERRIDE">已安装合成 Mock</option></select></label><div class="actions"><button :disabled="!basis.basis.allowed_commands.some(command=>command==='SET_DEFAULTS')" @click="save('DEFAULTS')">保存默认设置</button><button @click="local.defaults=JSON.parse(JSON.stringify(basis.defaults))">取消默认设置修改</button></div></section><section class="panel"><h2>模型连接</h2><p>连接元数据不等于供应商就绪。UNVERIFIED 表示未进行真实供应商验证；真实调用由后续能力接通。停用只阻断新受理与新发送，保留原任务查询与账务恢复。</p><fieldset v-for="(c,index) in local.connections" :key="index"><legend>{{c.connection_id||'新连接'}}</legend><label>名称<input v-model="c.name"></label><label>连接标识<input v-model="c.connection_id" :readonly="c.revision!=='0'"></label><template v-if="c.connection_id==='mock-local'"><p>已安装 synthetic-text-v1 · provider r0-mock-provider · 无端点与密钥别名。</p></template><template v-else><label>供应商登记<select v-model="c.provider_ref"><option value="">请选择</option><option v-for="ref in local.reference_catalog.providers.filter(r=>r.enabled)" :key="ref.ref_id" :value="ref.ref_id">{{ref.label}}</option></select></label><label>模型标识<input v-model="c.model_id"></label><label>已登记端点别名<select v-model="c.endpoint_alias_ref"><option value="">请选择</option><option v-for="ref in local.reference_catalog.endpoint_aliases.filter(r=>r.enabled)" :key="ref.ref_id" :value="ref.ref_id">{{ref.label}}</option></select></label><label>已登记密钥别名<select v-model="c.secret_alias_ref"><option value="">请选择</option><option v-for="ref in local.reference_catalog.secret_aliases.filter(r=>r.enabled)" :key="ref.ref_id" :value="ref.ref_id">{{ref.label}}</option></select></label></template><label>状态<select v-model="c.status"><option value="UNVERIFIED">UNVERIFIED · 未验证</option><option value="DISABLED">DISABLED · 停用</option><option v-if="c.connection_id!=='mock-local'" value="R1_REQUIRED">R1_REQUIRED · 待后续接入</option></select></label><div class="actions"><button :disabled="!basis.basis.allowed_commands.some(command=>command==='UPSERT_CONNECTION_METADATA')" @click="connection(c)">保存连接</button><button :disabled="c.revision==='0'||!basis.basis.allowed_commands.some(command=>command==='DISABLE_CONNECTION')" @click="connection(c,true)">停用连接</button></div></fieldset><div class="actions"><button :disabled="local.connections.length>=64" @click="addConnection">添加登记元数据</button><button @click="local.connections=JSON.parse(JSON.stringify(basis.connections))">取消连接修改</button></div></section><section class="panel"><h2>额度策略</h2><p>{{basis.quota_policy.hard_limit_source}}</p><label>已登记策略<select v-model="local.quota_policy.policy_ref"><option :value="null">尚未选择</option><option v-for="r in local.reference_catalog.quota_policies.filter(r=>r.enabled)" :key="r.ref_id" :value="r.ref_id">{{r.label}}</option></select></label><button :disabled="!basis.basis.allowed_commands.some(command=>command==='SET_QUOTA_POLICY')||!local.quota_policy.policy_ref" @click="save('QUOTA')">保存额度策略</button><button @click="local.quota_policy=JSON.parse(JSON.stringify(basis.quota_policy))">取消额度修改</button></section><section class="panel"><h2>本页通知偏好</h2><p>仅在当前获权页面显示任务状态或许可到期；不发送邮件、消息或后台推送。</p><label><input v-model="local.local_notifications.enabled" type="checkbox">启用本页状态提示</label><label><input v-model="local.local_notifications.events" type="checkbox" value="TASK_STATUS">任务状态</label><label><input v-model="local.local_notifications.events" type="checkbox" value="CONSENT_EXPIRY">许可到期</label><label>频率<select v-model="local.local_notifications.frequency"><option value="ON_OPEN">打开页面时</option><option value="IMMEDIATE">当前页面即时更新</option></select></label><button :disabled="!basis.basis.allowed_commands.some(command=>command==='SET_LOCAL_NOTIFICATIONS')" @click="save('NOTIFICATIONS')">保存通知偏好</button><button @click="local.local_notifications=JSON.parse(JSON.stringify(basis.local_notifications))">取消通知修改</button></section></template>
